begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(20);
create function pg_temp.m15_05_prepare_configuration(instance_id uuid,configuration jsonb) returns void language plpgsql as $$declare validation jsonb;begin
 validation:=public.m15_05_backup_control(instance_id,'backup-sql-fixture','policy/validate',jsonb_build_object('configuration',configuration));
 perform public.m15_05_backup_control(instance_id,'backup-sql-fixture','policy/validated',jsonb_build_object('configurationDigest',validation->'result'->>'configurationDigest'));
end $$;
create temporary table m15_05_test_values(k text primary key,v jsonb);
insert into m15_05_test_values values('configuration','{"sourceAlias":"source","repositoryAlias":"off-host","stagingAlias":"private-ram","keyAlias":"backup-key","targetProfile":"isolated-saas","residency":"eu","schedulingEnabled":false,"checkpointIntervalMinutes":30,"baseIntervalHours":24,"verificationIntervalDays":30,"retentionDays":30,"pauseLimitSeconds":120}');
select pg_temp.m15_05_prepare_configuration('15000000-0000-4000-8000-000000000005',(select v from m15_05_test_values where k='configuration'));
insert into m15_05_test_values select 'policy',public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','policy/update',jsonb_build_object('expectedVersion',0,'idempotencyKey','15000000-0000-4000-8000-000000000010','configuration',v)) from m15_05_test_values where k='configuration';
select is((select v->>'outcome' from m15_05_test_values where k='policy'),'ok','initial policy creation');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','policy/update',jsonb_build_object('expectedVersion',0,'idempotencyKey','15000000-0000-4000-8000-000000000010','configuration',(select v from m15_05_test_values where k='configuration')))->>'outcome','ok','policy replay succeeds');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','policy/update',jsonb_build_object('expectedVersion',0,'idempotencyKey','15000000-0000-4000-8000-000000000010','configuration',(select v||'{"residency":"us"}' from m15_05_test_values where k='configuration')))->>'outcome','conflict','changed policy idempotency conflicts');
insert into m15_05_test_values values('capture',public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/create','{"kind":"capture","expectedVersion":1,"idempotencyKey":"15000000-0000-4000-8000-000000000011"}'));
select is((select v->>'outcome' from m15_05_test_values where k='capture'),'ok','capture enqueue');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/create','{"kind":"capture","expectedVersion":1,"idempotencyKey":"15000000-0000-4000-8000-000000000011"}')->>'outcome','ok','capture replay');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/create','{"kind":"capture","expectedVersion":1,"idempotencyKey":"15000000-0000-4000-8000-000000000012"}')->>'outcome','conflict','one capture lane');
insert into m15_05_test_values values('claimed',public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','backup-worker','run/claim','{"workerId":"test-worker","kind":"capture"}'));
select is((select v->'result'->>'state' from m15_05_test_values where k='claimed'),'running','worker claims durably');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','backup-worker','run/heartbeat',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',2,'workerId','wrong-worker'))->>'outcome','conflict','lease owner fences');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000006','backup-worker','run/read',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed')))->>'outcome','not_found','cross-instance IDs hidden');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','backup-worker','run/complete',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',2,'workerId','test-worker','certificate','{}'::jsonb))->>'outcome','invalid','no incomplete certificate publication');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/cancel',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',1,'idempotencyKey','15000000-0000-4000-8000-000000000013'))->>'outcome','conflict','stale cancel conflicts');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/cancel',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',2,'idempotencyKey','15000000-0000-4000-8000-000000000013'))->'result'->>'state','cancelled','cancel wins publication race');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','backup-worker','run/complete',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',2,'workerId','test-worker','certificate','{}'::jsonb))->>'outcome','conflict','stale worker cannot publish');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/cancel',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',2,'idempotencyKey','15000000-0000-4000-8000-000000000013'))->>'outcome','ok','cancel replay retains result before version check');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/cancel',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',2,'idempotencyKey','15000000-0000-4000-8000-000000000099'))->>'outcome','conflict','changed cancel key cannot replay');
select ok((select count(*)=4 from public.audit_logs where action like 'backup.%' and actor_id in ('15000000-0000-4000-8000-000000000001','backup-worker')),'critical actions audited exactly once');
select ok((public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','cleanup/review',jsonb_build_object('runId',(select v->'result'->>'id' from m15_05_test_values where k='claimed')))->'result'->'blockers') ? 'authority_unknown','unknown cleanup authority blocks');
select is(public.m15_05_backup_control('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','run/create',jsonb_build_object('kind','verification','parentRunId',(select v->'result'->>'id' from m15_05_test_values where k='claimed'),'expectedVersion',1,'idempotencyKey','15000000-0000-4000-8000-000000000014','targetProfile','isolated-saas'))->>'outcome','not_found','uncertified parent cannot restore');
select is(public.m15_05_backup_assurance('00000000-0000-4000-8000-000000000099','15000000-0000-4000-8000-000000000001',25)->>'outcome','forbidden','forged tenant lacks assurance');
select ok(not public.m15_05_configuration_valid((select v||'{"pauseLimitSeconds":121}' from m15_05_test_values where k='configuration')),'hard pause limit');
select * from finish();
rollback;
